import local.thor.bilichannels.*;import java.util.*;import org.json.*;
public class FeedQualityTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static Video v(int n){return new Video(String.format("BV%010d",n),"video "+n,"","",n,n,90,false);}
 static JSONObject track(int q,int codec)throws Exception{return new JSONObject().put("id",q).put("codecid",codec).put("baseUrl","https://cdn.test/"+q);}
 public static void main(String[] args)throws Exception{
  FeedPager cached=new FeedPager();cached.seed(Arrays.asList(v(99)));cached.accept(cached.begin(false),new FeedPager.Page(Arrays.asList(v(1)),1,true,""));check(cached.items.size()==1&&cached.items.get(0).id.equals(v(1).id),"fresh first page replaces startup disk cache");
  FeedPager pager=new FeedPager();List<Video> same=pager.items;int token=pager.begin(false);check(pager.begin(false)==-1,"one inflight page");pager.accept(token,new FeedPager.Page(Arrays.asList(v(1),v(2)),1,true,"a"));Video first=pager.items.get(0);token=pager.begin(false);pager.accept(token,new FeedPager.Page(Arrays.asList(v(2),v(3)),2,true,"b"));check(pager.items==same&&pager.items.get(0)==first&&pager.items.size()==3,"append retains list and objects and deduplicates");
  token=pager.begin(false);pager.fail(token,"offline");check(pager.page==2&&pager.cursor.equals("b")&&pager.more&&!pager.loading,"network error retains cursor and allows retry");token=pager.begin(false);pager.accept(token,new FeedPager.Page(Arrays.asList(v(4)),3,true,"c"));check(pager.page==3&&pager.items.size()==4,"retry appends the failed page");
  int stale=pager.begin(false),fresh=pager.begin(true);check(pager.items.size()==4,"refresh keeps old content until successful");check(!pager.accept(stale,new FeedPager.Page(Arrays.asList(v(5)),4,true,"d")),"stale pagination ignored after refresh");pager.accept(fresh,new FeedPager.Page(Arrays.asList(v(8)),1,true,"new"));check(pager.items==same&&pager.items.size()==1&&pager.items.get(0).id.equals(v(8).id),"refresh atomically replaces stable list");
  for(int page=2;page<=4;page++){token=pager.begin(false);pager.accept(token,new FeedPager.Page(Arrays.asList(v(8)),page,true,""));}check(pager.page==4&&pager.more&&!pager.error.isEmpty(),"duplicate pages are skipped with bounded automatic work");token=pager.begin(false);pager.accept(token,new FeedPager.Page(Arrays.asList(v(9)),5,false,""));check(pager.items.size()==2&&!pager.more&&pager.error.isEmpty()&&pager.begin(false)==-1,"explicit retry advances past duplicates to server EOF");
  token=pager.begin(true);pager.fail(token,"timeout");check(pager.items.size()==2&&!pager.loading,"failed refresh preserves content");token=pager.begin(false);check(token>=0&&pager.refreshing,"gesture retries failed refresh even after previous EOF");pager.accept(token,new FeedPager.Page(Arrays.asList(v(10)),1,true,"fresh"));check(pager.page==1&&pager.items.get(0).id.equals(v(10).id),"refresh retry uses first page");pager.clear();check(pager.page==0&&pager.items.isEmpty()&&pager.more,"account reset clears cursor and entries");
  List<Video> many=new ArrayList<>();for(int i=0;i<40;i++)many.add(v(i));pager.seed(many);check(!pager.nearEnd(6,6)&&pager.nearEnd(28,6),"prefetch starts two screens before end");
  JSONObject row=new JSONObject().put("bvid",v(1).id).put("title","one");JSONObject response=new JSONObject().put("list",new JSONArray().put(row)).put("no_more",false);check(ApiModels.feedPage(response,2,false).more,"short popular page follows server EOF not page size");response.put("no_more",true);check(!ApiModels.feedPage(response,2,false).more,"popular server end");
  check(ApiModels.feedPage(new JSONObject().put("item",new JSONArray()),3,true).more,"temporary empty recommendations are retryable, not false EOF");
  JSONObject archive=new JSONObject().put("bvid",v(2).id).put("title","dynamic");JSONObject module=new JSONObject().put("module_author",new JSONObject().put("name","up")).put("module_dynamic",new JSONObject().put("major",new JSONObject().put("archive",archive)));JSONObject data=new JSONObject().put("items",new JSONArray().put(new JSONObject().put("modules",module))).put("offset","next").put("has_more",1);FeedPager.Page dyn=ApiModels.followingPage(data,2,"prior");check(dyn.items.size()==1&&dyn.more&&dyn.cursor.equals("next"),"dynamic continuation and archive parsing");boolean rejected=false;try{ApiModels.followingPage(data,3,"next");}catch(Exception e){rejected=true;}check(rejected,"repeated dynamic cursor is retryable error");
  SearchPager search=new SearchPager();search.reset("汽车");token=search.begin();search.accept(token,new SearchPager.Page(Arrays.asList(v(1)),1,5,true,true));token=search.begin();check(search.accept(token,new SearchPager.Page(Arrays.asList(v(1)),2,5,true,true))&&search.page==2&&search.items.size()==1&&search.error.isEmpty(),"confirmed duplicate search page advances cursor");JSONObject searchJson=new JSONObject().put("page",3).put("numPages",5).put("result",new JSONArray());check(ApiModels.searchPage(searchJson,3).more,"empty filtered search page cannot erase known remaining pages");
  JSONObject dash=new JSONObject().put("video",new JSONArray().put(track(16,7)).put(track(64,7)).put(track(80,7)).put(track(120,7)).put(track(127,12))).put("audio",new JSONArray().put(new JSONObject().put("codecs","mp4a.40.2").put("baseUrl","https://cdn.test/a")));JSONObject playback=new JSONObject().put("quality",127).put("dash",dash);check(ApiModels.stream(playback,0).quality==120,"auto selects highest supported returned tier");playback.put("quality",64);check(ApiModels.stream(playback,0).quality==64,"auto respects server account ceiling even when higher tracks are listed");check(ApiModels.stream(playback,16).quality==16,"explicit lower choice is still respected");playback.put("quality",8);rejected=false;try{ApiModels.stream(playback,0);}catch(Exception e){rejected=true;}check(rejected,"never falls above explicit server ceiling");
  check(ApiModels.qualityName(0).equals("自动最高画质"),"auto setting label");
  System.out.println("PASS: "+checks+" feed pagination, stale response, retry and automatic quality cases");
 }
}
